import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const _=JSON.parse('{"title":"01 · KK三部曲与房价终极论战","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/notes/01_KK三部曲与房价终极论战.md","filePath":"topics/tianya/notes/01_KK三部曲与房价终极论战.md"}'),l={name:"topics/tianya/notes/01_KK三部曲与房价终极论战.md"};function u(i,t,g,q,a,e){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_01-·-kk三部曲与房价终极论战" tabindex="-1">01 · KK三部曲与房价终极论战 <a class="header-anchor" href="#_01-·-kk三部曲与房价终极论战" aria-label="Permalink to &quot;01 · KK三部曲与房价终极论战&quot;">​</a></h1><blockquote><p>精读范围：kk三部曲第1-3部（第2/3部docx为内容重叠的另一版本）、《一个炒房人的终极预测》、《北望帝都》、《降低房价的四项基本原则》（完整版/楼主版互为正帖与回帖）。三部曲整理本混有2018年评论与【PS】批注，笔记只取楼主正文。</p></blockquote><hr><h2 id="一、kk三部曲-kkndme-2010—2011" tabindex="-1">一、KK三部曲（kkndme，2010—2011） <a class="header-anchor" href="#一、kk三部曲-kkndme-2010—2011" aria-label="Permalink to &quot;一、KK三部曲（kkndme，2010—2011）&quot;">​</a></h2><p><strong>作者与年代</strong>：天涯房产观澜楼主 kkndme，2010年8月起连载（最早回帖2010-08-11），第3部含「2011年第一贴」。</p><p><strong>核心论点</strong></p><ol><li><strong>房价由精英收入决定</strong>：金字塔收入结构下顶端10%就是一亿多人，核心城市土地稀缺，&quot;房价不是由统计局的平均收入决定的，而是精英的平均收入决定的&quot;；均价、租售比、空置率都不是定价变量。</li><li><strong>调控的真实意图是&quot;国家队垄断&quot;</strong>：地方政府卖地无风险、风险甩给银行和中央；调控意在踢出小开发商小炒客，让央企从一级市场（规划、拆迁、开发）一条龙垄断，并借公租房走向房租垄断。</li><li><strong>通胀是统治工具，房地产是蓄水池</strong>：印钞流向精英，房子吸收超发货币；一旦调控压住成交量，钱就流向大蒜绿豆姜，物价反推房价租金。</li><li><strong>房产税难产且会转嫁</strong>：动权贵的税征不动，动百姓的税只会加租；公租房&quot;打个9折安抚底层，黑锅由竞争房源的房东背&quot;。</li><li><strong>双轨制是万能钥匙</strong>：保障房=体制内福利房，经适房被权贵牟利；体制外自生自灭，以房养老是唯一体面。</li><li><strong>实操框架</strong>：自住随时可买、调控期是选房窗口；投资只买省会以上核心地段，不碰中小城市与偏远旅游城市；三个出手信号——新盘低于二手、看房人增多、土地流拍。</li><li><strong>历史周期观</strong>：王安石青苗法说明惠民政策会被官僚变成敛财工具；土地兼并是王朝中期标志，&quot;历朝历代发展到中期，政策都是打劫穷人&quot;。</li></ol><p><strong>方法论/可复用框架</strong>：利益分析法——&quot;辨别利益是看透一切事物真相的武器&quot;；以明朝货币崩溃、摊丁入亩、青苗法做制度对照；把政策翻译成&quot;谁受益、谁背锅、谁买单&quot;。</p><p><strong>金句</strong></p><ul><li>&quot;辨别利益是看透一切事物真相的武器。&quot;</li><li>&quot;买房抗通胀是一个没有办法的办法。&quot;</li><li>&quot;房地产的实质就是大型城市的准入证。&quot;</li></ul><p><strong>预测对照（→2026）</strong></p><ul><li><strong>准</strong>：2010-2021房价长牛、房租翻倍、中西部省会补涨、调控期确为选房窗口、技术工收入跑赢小白领、房产税至今未全国开征（&quot;征收难度大，不了了之&quot;应验）；&quot;分化时代&quot;（核心地段、地铁、大中户型涨，远郊滞涨）命中2015-2021。</li><li><strong>不准</strong>：&quot;土地垄断不改房价就不会真跌&quot;在2021年后失效，2022-2026全国普跌、恒大碧桂园爆雷；&quot;不可能软着陆&quot;以迟到的硬着陆兑现，但社会未如他所言&quot;没人关心房价&quot;；保租房面向体制外，房租垄断未成真。</li></ul><hr><h2 id="二、《一个炒房人的终极预测——调控将彻底失败》-2010" tabindex="-1">二、《一个炒房人的终极预测——调控将彻底失败》（2010） <a class="header-anchor" href="#二、《一个炒房人的终极预测——调控将彻底失败》-2010" aria-label="Permalink to &quot;二、《一个炒房人的终极预测——调控将彻底失败》（2010）&quot;">​</a></h2><p><strong>作者与年代</strong>：自称40岁、有实业公司的职业炒房人（自称曾持有50余套房），2010年4月新国十条后发帖。</p><p><strong>核心论点</strong></p><ol><li><strong>调控打不着真炒家</strong>：实业贷款、抵押、民间借贷多渠道融资，限购限贷只误伤想保值的白领；调控实质是财富再分配，不是降房价。</li><li><strong>物业税（房产税）约2015年开征，但为财政不为降价</strong>：土地卖完后政府要填补开支；开征也压不住房价，只会推高租金。</li><li><strong>一线城市没有大泡沫</strong>（对比东京、首尔），调控后的下跌是炒家抄底机会；&quot;北京租金将是现在的5到10倍&quot;。</li><li><strong>政策-媒体五阶段剧本</strong>：揭露暴涨→表决心→夸大成果→开发商集体&quot;做秀式&quot;降价要挟政府→政府托市救市。</li><li><strong>狼与羊的寓言</strong>：政府不会让羊吃绝，也不会让羊翻身；中国15年内不会是纺锤形社会，只能是20%精英+80%金字塔底。</li><li><strong>保障房注定失败</strong>：建得比商品房好，必被有权有办法者占有——他自曝炒房客也持有经适房。</li><li><strong>人口窗口</strong>：2015-2020人口红利结束，&quot;留给你们只有10年时间&quot;。</li></ol><p><strong>方法论/可复用框架</strong>：第一人称资金渠道分析；把每轮调控当有脚本的连续剧来读（五阶段至今是解读政策周期的模板）；城市价值看&quot;辐射腹地的外部购买力&quot;而非本地收入。</p><p><strong>金句</strong></p><ul><li>&quot;老虎喜欢吃羊，但不会把羊都吃光……不过等羊再养得胖点。&quot;</li><li>&quot;炒房目前是老百姓唯一可以通过头脑和勤奋进行有效资产增值的方法&quot;——因为&quot;楼市还没有真正的大庄家&quot;。</li></ul><p><strong>预测对照（→2026）</strong></p><ul><li><strong>准</strong>：调控十余年压不住价（直到2016&quot;房住不炒&quot;+2021去杠杆才逆转）；人口红利如期见顶（2022年负增长）；媒体五阶段在2010-2015历轮调控中反复应验；保障房沦为政绩与福利房。</li><li><strong>不准</strong>：房产税至今未全国落地；北京租金实际只涨约2倍而非5-10倍；&quot;一线永不崩&quot;被2021-2026大熊市击穿；他赌咒燕郊&quot;十月全面崩溃&quot;迟到7年——2017年环京真腰斩，但与他无关。</li></ul><hr><h2 id="三、《北望帝都-十年内北京四环内均价八万》-2010-11-08" tabindex="-1">三、《北望帝都：十年内北京四环内均价八万》（2010.11.08） <a class="header-anchor" href="#三、《北望帝都-十年内北京四环内均价八万》-2010-11-08" aria-label="Permalink to &quot;三、《北望帝都：十年内北京四环内均价八万》（2010.11.08）&quot;">​</a></h2><p><strong>作者与年代</strong>：楼主&quot;北望帝都&quot;，2010年11月8日一发惊人，2018年被考古封神。</p><p><strong>核心论点</strong></p><ol><li><strong>十年点位表</strong>：北京四环内8万、上海7万、杭州7万、深广4-6万、津汉宁成渝西3-4万。</li><li><strong>不要用自己的收入衡量房价</strong>：下乡调研发现&quot;农民的有钱程度让人吃惊&quot;，有钱农民+拆迁户是隐藏购买力；拆村并居是把9亿农民逼向商品房市场的新圈地运动。</li><li><strong>地缘大战略</strong>：中国不该争海洋霸权，应以欧亚高铁+亚非高铁争大陆霸权，输出国力与人民币——西安、成都、重庆是枢纽（已引2010年10月欧亚高铁新闻）。</li><li><strong>卡位论</strong>：博弈结束后&quot;及早占位的人固化成阶层&quot;，买房至少&quot;避免滑入下一个层次&quot;；通胀之下攒钱只会缩水。</li></ol><p><strong>方法论/可复用框架</strong>：基建与地缘资本开支推演城市价值（国家下一个十年在哪砸钱）；&quot;城市卡位&quot;叙事，房产是留在牌桌上的资格。</p><p><strong>金句</strong></p><ul><li>&quot;十年之内，任何时候买房都是对的。&quot;</li><li>&quot;房价平稳是理想，我说房价上升不过是一个事实。&quot;</li></ul><p><strong>预测对照（→2026）</strong></p><ul><li><strong>准</strong>：北京四环内均价2020-2021年前后触及8万一线；&quot;一带一路&quot;2013年提出、中欧班列成网；拆村并居推高二线。</li><li><strong>不准</strong>：人民币没升到3:1，反在7上下徘徊；十年GDP超美未实现；深圳远超4-6万（2021年破10万），杭州西安成都远未到3-7万；2022年后全国普跌，&quot;任何时候买房都对&quot;成了反面教材——点位对了一半，时点哲学错了。</li></ul><hr><h2 id="四、《全面阐述降低房价的四项基本原则》-孤独的思想-2005-11-11" tabindex="-1">四、《全面阐述降低房价的四项基本原则》（孤独的思想，2005.11.11） <a class="header-anchor" href="#四、《全面阐述降低房价的四项基本原则》-孤独的思想-2005-11-11" aria-label="Permalink to &quot;四、《全面阐述降低房价的四项基本原则》（孤独的思想，2005.11.11）&quot;">​</a></h2><p><strong>作者与年代</strong>：楼主&quot;孤独的思想&quot;，2005年11月发于&quot;水煮房价&quot;版，本组最早的&quot;改良派&quot;文本。</p><p><strong>核心论点（四项基本原则）</strong></p><ol><li><strong>增加供给</strong>：以香港&quot;八万五公屋&quot;为例，供给预期本身就能砸下房价；并警告&quot;对二手房征税越多，房源冻结越多，反而逼人买新盘、抬高新房&quot;——以2004年杭州、深圳为证。</li><li><strong>破除垄断</strong>：土地被政府独家垄断（2000年招拍挂、2004年&quot;831大限&quot;后地价连翻，出让金成&quot;第二财政&quot;）；建房权被开发商垄断，城市平民没有自建房权，于凌罡合作建房是破局号角。</li><li><strong>降低成本</strong>：地价、税费、灰色成本终将转嫁购房者。</li><li><strong>鼓励竞争</strong>：反对借&quot;行业洗牌&quot;提高门槛消灭中小开发商——那是打弱助强，会造就价格同盟。</li><li><strong>附赠预言</strong>：因70年使用权逐年递减，二手房长期必然&quot;自由落体&quot;式走低。</li></ol><p><strong>方法论/可复用框架</strong>：教科书式供求—垄断—竞争分析，以家电业价格战为镜；与后来KK的&quot;垄断永恒论&quot;恰成两极。</p><p><strong>金句</strong></p><ul><li>&quot;空置率越高，开发商压力越大，低价抛售的可能性越大。&quot;（戳破&quot;空置危及银行&quot;论）</li><li>&quot;如果供给充足，炒房者不攻自溃。&quot;</li></ul><p><strong>预测对照（→2026）</strong></p><ul><li><strong>部分准</strong>：二手房高税费冻结流动性的机制被反复验证（2021年二手房指导价是极端版）；&quot;老破小贬值快于新房&quot;在2023-2026年迟到显形，使用权焦虑重回议题。</li><li><strong>不准</strong>：四项原则一条都没被采纳——土地垄断没破、建房权没放开；行业集中度反而空前（恒大、碧桂园、融创以爆雷收场）；2022-2026房价确实降了，但是去杠杆下供给过剩的崩盘，而非他设计的有序降价。</li></ul><hr><h2 id="五、总览与心得" tabindex="-1">五、总览与心得 <a class="header-anchor" href="#五、总览与心得" aria-label="Permalink to &quot;五、总览与心得&quot;">​</a></h2><p><strong>共同世界观</strong>：这组帖子从2005到2011年，勾勒出同一个判断——中国房价从来不是供需问题，而是**财政（土地第二财政）×货币（超发与蓄水池）×权力（双轨制与垄断）**的铁三角。四项基本原则相信改制度可以降价；KK与炒房人断定制度不会改，于是民间只剩两条路：<strong>尽早占位（买房抗通胀），或彻底离场</strong>。</p><p><strong>共同的盲点</strong>：所有人都默认国家信用与货币扩张永续，没人推演&quot;主动去杠杆+人口拐点&quot;的组合拳。2021年后的楼市大逆转证明：再严密的利益分析，一旦把&quot;政府绝不允许跌&quot;设为公理，就会在政策目标切换时失效——他们&quot;对&quot;的那十年，养成了读者对确定性的迷信。</p><p><strong>对2026年读者的价值</strong>：不是抄答案（点位表早已过期），而是带走三件工具：①<strong>利益分析法</strong>（谁受益、谁背锅、谁买单）；②<strong>政策-媒体周期剧本</strong>（五阶段，识别在第几幕）；③<strong>城市分化框架</strong>（人口流入、配套、稀缺位置才抗跌）。外加一条教训：对任何&quot;这一次不一样&quot;的叙事，先写下它的失效条件。</p>',47)])])}const h=o(l,[["render",u]]);export{_ as __pageData,h as default};
